/**
 * Short, coder-facing summaries of what the CMS OASIS-E2 manual says per item, generated by Claude once per
 * (manual version, code) from that item's section and cached under `${DATA_DIR}/manual-notes/<version>/<code>.json`.
 */
import fs from "node:fs";
import path from "node:path";
import { query } from "@anthropic-ai/claude-agent-sdk";
import type { Config } from "../config.js";
import { manualItems } from "./codes.js";
import { loadManual, type ManualIndex, type ManualItem } from "./lookup.js";

export type CmsVerdict = "covered" | "partial" | "not-in-manual";

/** One manual item with its 2–5 line summary, each line ending in its page(s). */
export interface ManualNote {
  code: string;
  title: string;
  pages: [number, number];
  ranges?: [number, number][];
  notes: string;
}

/** What triage says about an item: the codes it's about and whether the manual settles the reported problem. */
export interface TriageCms {
  codes: string[];
  verdict: CmsVerdict;
  answer: string;
}

/** What an agenda card carries: triage's answer plus the notes of the codes it named. */
export interface CardCms {
  codes: { code: string; title: string; pages: [number, number]; notes: string }[];
  verdict?: CmsVerdict;
  answer?: string;
}

/** Turns a prompt into summary lines; injectable so tests don't call the model. */
export type NotesModel = (prompt: string) => Promise<string[]>;

const CONCURRENCY = 4;
const TIMEOUT_MS = 5 * 60_000;
const MAX_CARD_CODES = 6;
const CONVENTIONS = /^1\.5\.8 /;
const ADL_CONVENTIONS = /^1\.5\.8\.2 /;

/**
 * Notes for the manual items behind `codes` (codes or Lime form keys; deduped, GG parents included). Cached notes
 * are read back without a model call; a code that fails is logged and left out.
 */
export async function manualNotes(
  config: Pick<Config, "CLAUDE_MODEL" | "DATA_DIR">,
  codes: string[],
  opts: { manual?: ManualIndex | null; generate?: NotesModel } = {},
): Promise<ManualNote[]> {
  const manual = opts.manual === undefined ? loadManual() : opts.manual;
  if (!manual) return [];
  const generate = opts.generate ?? claudeNotes(config);
  const dir = path.join(config.DATA_DIR, "manual-notes", manual.version);
  const items = manualItems(manual, codes);
  const notes: (ManualNote | null)[] = [];
  for (let i = 0; i < items.length; i += CONCURRENCY) {
    notes.push(...(await Promise.all(items.slice(i, i + CONCURRENCY).map((item) => noteFor(manual, item, dir, generate)))));
  }
  return notes.filter((n): n is ManualNote => Boolean(n));
}

async function noteFor(manual: ManualIndex, item: ManualItem, dir: string, generate: NotesModel): Promise<ManualNote | null> {
  const file = path.join(dir, `${item.code}.json`);
  try {
    if (fs.existsSync(file)) return JSON.parse(fs.readFileSync(file, "utf8")) as ManualNote;
    const lines = (await generate(notesPrompt(manual, item))).map((l) => l.trim()).filter(Boolean);
    if (!lines.length) throw new Error("no notes returned");
    const note: ManualNote = {
      code: item.code,
      title: item.title,
      pages: item.pages,
      ...(item.ranges ? { ranges: item.ranges } : {}),
      notes: lines.join("\n"),
    };
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(file, JSON.stringify(note, null, 2));
    return note;
  } catch (error) {
    console.error(`[manual] couldn't summarize ${item.code}`, error);
    return null;
  }
}

/** The prompt for one item: its section text, plus the general conventions (and the ADL ones for M18xx items). */
export function notesPrompt(manual: ManualIndex, item: ManualItem): string {
  const general = manual.general.filter((g) => CONVENTIONS.test(g.title) || (item.code.startsWith("M18") && ADL_CONVENTIONS.test(g.title)));
  const ranges = (item.ranges ?? [item.pages]).map(pageRange).join(", ");
  return `
Summarize what the CMS OASIS-E2 Guidance Manual (${manual.version}) says about ${item.code} (${item.title}) for a coder
who checks AI-filled OASIS answers. Write 2–5 short lines, one point each, covering what matters most of: what the
item measures, response options / scale highlights, key coding tips, whether a dash is valid, common pitfalls.
Use only the text below and don't add anything it doesn't say. End every line with its page(s), e.g. "(p.125)".
The section spans ${ranges}; a line like [p.157] marks where each page starts, so cite the exact page(s) a point comes from.
${general.map((g) => `\nGeneral conventions, ${g.title} (${pageRange(g.pages)}):\n${g.text}\n`).join("")}
${item.code} section (${ranges}):
${item.text}
`.trim();
}

const NOTES_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["notes"],
  properties: { notes: { type: "array", items: { type: "string" }, minItems: 2, maxItems: 5 } },
} as const;

/** The real model: same Agent SDK call as triage, low effort, no tools, structured output. */
function claudeNotes(config: Pick<Config, "CLAUDE_MODEL">): NotesModel {
  return async (prompt) => {
    const abortController = new AbortController();
    const timer = setTimeout(() => abortController.abort(), TIMEOUT_MS);
    try {
      for await (const message of query({
        prompt,
        options: {
          model: config.CLAUDE_MODEL,
          effort: "low",
          tools: [],
          permissionMode: "dontAsk",
          settingSources: [],
          outputFormat: { type: "json_schema", schema: NOTES_SCHEMA },
          abortController,
        },
      })) {
        if (message.type !== "result") continue;
        if (message.subtype !== "success" || !message.structured_output) throw new Error(`Notes stopped early (${message.subtype})`);
        return (message.structured_output as { notes: string[] }).notes;
      }
      throw new Error("Notes returned no result");
    } finally {
      clearTimeout(timer);
    }
  };
}

/** "p.125" or "p.125–126". */
export function pageRange([from, to]: [number, number]): string {
  return from === to ? `p.${from}` : `p.${from}–${to}`;
}

/** The notes as a compact prompt section, cut at whole notes once `maxChars` is reached. */
export function describeNotes(notes: ManualNote[], maxChars = 16_000): string {
  const parts: string[] = [];
  let size = 0;
  for (const n of notes) {
    const text = `${n.code} ${n.title} (${pageRange(n.pages)})\n${n.notes}`;
    if (size + text.length > maxChars) break;
    parts.push(text);
    size += text.length + 2;
  }
  return parts.join("\n\n");
}

/**
 * The card's manual block from triage's answer: each named code resolved to its manual item (GG parent included),
 * with its notes when they were generated. Undefined when triage gave no answer.
 */
export function cardCms(cms: TriageCms | undefined, notes: ManualNote[], manual: ManualIndex | null): CardCms | undefined {
  if (!cms) return undefined;
  const byCode = new Map(notes.map((n) => [n.code, n]));
  const codes = (manual ? manualItems(manual, cms.codes) : [])
    .slice(0, MAX_CARD_CODES)
    .map((i) => ({ code: i.code, title: i.title, pages: i.pages, notes: byCode.get(i.code)?.notes ?? "" }));
  return { codes, verdict: cms.verdict, answer: cms.answer };
}
